/* test_kntwcc.c — known-answer tests for kn_twcc (slice 5l).
 *
 * Vectors: streamer/src/kn_twcc_kat_vectors.h, generated by
 * tools/twcc_reference.py — an independent Python port of the str0m
 * twcc.rs semantics (with kn_twcc's documented deviations: RUN-only
 * chunks, 1024 ring, conservative budget, dropped-history floor). The
 * generator re-parses every emitted report with a draft-§3.1 decoder and
 * reconstructs seq coverage + arrival times before emitting, so a C/PY
 * disagreement here means one of the two ports drifted from str0m.
 *
 * Scenarios (see the generator for the event scripts):
 *   steady   — 10ms cadence, 4 reports, reference_time stepping
 *   loss     — NotReceived run between Received runs
 *   reorder  — out-of-order inserts, exact-dup ignore, pre-epoch
 *              pull-back (large-negative first delta, clamped ref_time),
 *              trim floor + below-floor late drop
 *   large    — large/negative deltas, ref_time 10/129, old-time drop
 *   wrap     — 16-bit seq wrap 65534..1 -> ext 65534..65537
 *   evict    — 1100 receipts, ring evicts 76, MAX_DELTAS truncation,
 *              trim-to-100, empty third build
 *   budget   — out_len 64 truncates at 37 receipts, rest rides the
 *              next 1200-byte build
 *   rereport — late fill pulls report_from back (keep_reported window)
 * Runs on Linux host and Win7 target. */
#include "kn/kn_twcc.h"
#include "kn_twcc_kat_vectors.h"
#include "test_port.h"

#include <stdio.h>
#include <string.h>

static const char *scen_name(int s)
{
    static const char *names[] = { "steady", "loss", "reorder", "large",
                                   "wrap", "evict", "budget", "rereport" };
    return (s >= 0 && s < K_KAT_TWCC_NSCEN) ? names[s] : "?";
}

static void test_scenarios(void)
{
    int s;
    for (s = 0; s < K_KAT_TWCC_NSCEN; ++s) {
        kn_twcc t;
        unsigned ev0 = k_kat_twcc_scen_ev_off[s];
        unsigned evn = k_kat_twcc_scen_ev_len[s];
        unsigned ri = k_kat_twcc_scen_rep_off[s];
        unsigned ri_end = k_kat_twcc_scen_rep_off[s + 1];
        unsigned mism = 0, first_bad = 0, builds = 0, k;
        char name[96];

        kn_twcc_init(&t);
        for (k = 0; k < evn; ++k) {
            unsigned char cmd = k_kat_twcc_ev_cmd[ev0 + k];
            if (cmd == 0) {
                kn_twcc_record(&t, k_kat_twcc_ev_seq[ev0 + k],
                               k_kat_twcc_ev_time[ev0 + k]);
            } else {
                uint8_t out[1200];
                size_t ol = (cmd == 2) ? 64u : 1200u;
                size_t n = kn_twcc_build(&t, K_KAT_TWCC_SENDER_SSRC,
                                         K_KAT_TWCC_MEDIA_SSRC, out, ol);
                if (n != (size_t)k_kat_twcc_rep_len[ri] ||
                    (n && memcmp(out,
                                 k_kat_twcc_rep_blob + k_kat_twcc_rep_off[ri],
                                 n) != 0)) {
                    if (!mism) first_bad = builds;
                    ++mism;
                }
                ++ri;
                ++builds;
            }
        }
        snprintf(name, sizeof name, "%s: %u reports byte-exact",
                 scen_name(s), builds);
        if (mism) printf("  %s: %u mismatch(es), first at report %u\n",
                         scen_name(s), mism, first_bad);
        CHECK(mism == 0 && ri == ri_end, name);

        snprintf(name, sizeof name,
                 "%s: counters rec/dup/late/old/evict/trunc", scen_name(s));
        CHECK(t.recorded         == k_kat_twcc_counters[s][0] &&
              t.dup_ignored      == k_kat_twcc_counters[s][1] &&
              t.late_dropped     == k_kat_twcc_counters[s][2] &&
              t.old_time_dropped == k_kat_twcc_counters[s][3] &&
              t.evicted          == k_kat_twcc_counters[s][4] &&
              t.reports_truncated == k_kat_twcc_counters[s][5], name);
    }
}

static void test_api_edges(void)
{
    kn_twcc t;
    uint8_t out[64];
    size_t n;

    kn_twcc_init(&t);
    kn_twcc_record(NULL, 1, 1);                    /* must not crash */
    CHECK(kn_twcc_build(&t, 1, 2, out, sizeof out) == 0,
          "empty register -> no report");
    CHECK(kn_twcc_build(NULL, 1, 2, out, sizeof out) == 0, "NULL reg -> 0");
    CHECK(kn_twcc_has_unreported(NULL) == 0, "NULL has_unreported -> 0");
    CHECK(kn_twcc_has_unreported(&t) == 0, "empty -> no unreported");

    kn_twcc_record(&t, 7, 1000000);
    CHECK(kn_twcc_has_unreported(&t) == 1, "record -> unreported");
    CHECK(kn_twcc_build(&t, 1, 2, out, 24) == 0, "out_len < 28 -> 0");
    CHECK(kn_twcc_build(&t, 1, 2, NULL, 64) == 0, "NULL out -> 0");
    CHECK(kn_twcc_has_unreported(&t) == 1,
          "refused builds left the receipt pending");

    /* the minimal legal report: 20 fixed + one run chunk + one small
     * delta (0) = 23 -> pad 1 -> 24 bytes, P bit set, pad count last. */
    n = kn_twcc_build(&t, 1, 2, out, 28);
    CHECK(n == 24 && out[0] == 0xAFu && out[1] == 205u &&
          out[2] == 0 && out[3] == 5 &&            /* length = 24/4-1 */
          out[12] == 0 && out[13] == 7 &&          /* base_seq */
          out[14] == 0 && out[15] == 1 &&          /* status_count */
          out[19] == 0 &&                          /* fb_count (first) */
          out[20] == 0x20 && out[21] == 0x01 &&    /* Run: small x1 */
          out[22] == 0 &&                          /* delta 0 */
          out[23] == 1,                            /* pad count */
          "minimal report wire layout (24B, P bit)");
    CHECK(kn_twcc_has_unreported(&t) == 0, "consumed -> no unreported");

    /* fb_count increments per generated report (str0m pre-increment) */
    kn_twcc_record(&t, 8, 1010000);
    n = kn_twcc_build(&t, 1, 2, out, 28);
    CHECK(n == 24 && out[19] == 1, "fb_count = 1 on the second report");

    kn_twcc_record(&t, 8, 1020000);                /* exact dup */
    CHECK(t.dup_ignored == 1, "exact duplicate ignored + counted");
    CHECK(kn_twcc_has_unreported(&t) == 0, "dup produced nothing reportable");
}

static void test_wrap_extension(void)
{
    kn_twcc t;
    uint8_t out[1200];
    size_t n;

    kn_twcc_init(&t);
    kn_twcc_record(&t, 65535, 4000000);
    kn_twcc_record(&t, 0,     4010000);            /* ext 65536 */
    kn_twcc_record(&t, 1,     4020000);            /* ext 65537 */
    CHECK(t.recorded == 3 && t.late_dropped == 0,
          "wrap: all three receipts kept (ext 65535..65537)");
    n = kn_twcc_build(&t, K_KAT_TWCC_SENDER_SSRC, K_KAT_TWCC_MEDIA_SSRC,
                      out, sizeof out);
    /* one run chunk of 3 small deltas: 20 + 2 + 3 = 25 -> pad 3 -> 28 */
    CHECK(n == 28 && out[12] == 0xFF && out[13] == 0xFF &&  /* base_seq */
          out[14] == 0 && out[15] == 3 &&                   /* count 3 */
          out[20] == 0x20 && out[21] == 0x03,               /* Run x3 */
          "wrap: single report covers the 16-bit boundary");
}

int main(void)
{
    test_scenarios();
    test_api_edges();
    test_wrap_extension();
    return kn_test_summary("test_kntwcc");
}
